def compute(vars):
    operating_income_increase = vars["v2"]
    if operating_income_increase == 0:
        return None

    ratio = vars["v1"] / operating_income_increase
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "higher_pricing": vars["v1"],
            "operating_income_increase": operating_income_increase,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
